// PHI — le ratio d'organisation naturel
export const PHI = 1.618033988749895;

// Seuil de symétrie = même seuil que CanResonate (639 Hz)
// Une symétrie < 0.7 = erreur visible avant d'être lue
export const SYMMETRY_THRESHOLD = 0.7;

export interface GeometricNode {
  readonly id:        number;
  readonly event:     SystemEvent;
  readonly children:  readonly GeometricNode[];
  readonly depth:     number;      // profondeur fractale
  readonly symmetry:  number;      // 0.0–1.0
}

export function isSymmetryBroken(node: GeometricNode): boolean {
  return node.symmetry < SYMMETRY_THRESHOLD;
}

// CanDetectError — l'asymétrie est visible avant d'être lue
export function canDetectError(node: GeometricNode): boolean {
  return isSymmetryBroken(node) ||
         node.children.some(c => isSymmetryBroken(c));
}

