pub const PHI: f64 = 1.618_033_988_749_895;
pub const SYMMETRY_THRESHOLD: f64 = 0.7;   // même seuil que can_resonate

#[derive(Debug, Clone)]
pub struct GeometricNode {
    pub id:       u64,
    pub event:    SystemEvent,
    pub children: Vec<GeometricNode>,
    pub depth:    u32,
    pub symmetry: f64,   // 0.0–1.0
}

/// CanDetectError — symétrie brisée = erreur visible avant d'être lue
pub fn can_detect_error(node: &GeometricNode) -> bool {
    node.symmetry < SYMMETRY_THRESHOLD ||
    node.children.iter().any(|c| c.symmetry < SYMMETRY_THRESHOLD)
}
